    expect(await readDetailSpacing(page)).toEqual(dayStatisticsSpacing);

    if (process.env.CAPTURE_ISSUE_195_EVIDENCE && isMobile) {
      await page.screenshot({
        fullPage: true,
        path: 'evidence/validation/issue-195-statistics-after-mobile.png',
      });
    }

