import { defineConfig, devices } from '@playwright/test';

const testPort = process.env.PLAYWRIGHT_PORT ?? '4173';
const baseURL = `http://127.0.0.1:${testPort}`;
const reuseProductionBuild = process.env.PLAYWRIGHT_REUSE_BUILD === '1';
const ciWorkers = Number.parseInt(process.env.PLAYWRIGHT_WORKERS ?? '2', 10);

if (process.env.CI && (!Number.isInteger(ciWorkers) || ciWorkers < 1)) {
  throw new Error('PLAYWRIGHT_WORKERS must be a positive integer when CI is enabled.');
}

const previewCommand = `npm run preview --workspace=@sport-analytics/frontend -- --host 127.0.0.1 --port ${testPort}`;
const webServerCommand = reuseProductionBuild
  ? previewCommand
  : `npm run build --workspace=@sport-analytics/frontend && ${previewCommand}`;

export default defineConfig({
  testDir: './tests/e2e',
  testMatch: '**/*.spec.ts',
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 1 : 0,
  timeout: process.env.CI ? 45_000 : 30_000,
  workers: process.env.CI ? ciWorkers : undefined,
  reporter: process.env.CI ? [['list'], ['html', { open: 'never' }]] : 'list',
  use: {
    baseURL,
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
  },
  webServer: {
    command: webServerCommand,
    env: {
      ...process.env,
      VITE_SUPABASE_URL: 'https://e2e.supabase.co',
      VITE_SUPABASE_PUBLISHABLE_KEY: 'e2e-public-key',
    },
    url: baseURL,
    reuseExistingServer: false,
    timeout: 120_000,
  },
  projects: [
    {
      name: 'desktop-chromium',
      use: {
        ...devices['Desktop Chrome'],
      },
    },
    {
      name: 'mobile-chromium',
      grep: /@mobile/,
      use: {
        ...devices['Pixel 7'],
      },
    },
  ],
});
import { spawn } from 'node:child_process';
import net from 'node:net';

function findAvailablePort() {
  return new Promise((resolve, reject) => {
    const server = net.createServer();
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      if (!address || typeof address === 'string') {
        server.close();
        reject(new Error('Could not select a Playwright preview port.'));
        return;
      }

      server.close((error) => (error ? reject(error) : resolve(address.port)));
    });
  });
}

const npmExecPath = process.env.npm_execpath;
if (!npmExecPath) {
  throw new Error('npm_execpath is unavailable. Start this command through npm.');
}

const port = await findAvailablePort();
const child = spawn(
  process.execPath,
  [npmExecPath, 'exec', '--', 'playwright', 'test', ...process.argv.slice(2)],
  {
    env: { ...process.env, PLAYWRIGHT_PORT: String(port) },
    stdio: 'inherit',
  },
);

child.once('error', (error) => {
  throw error;
});
child.once('exit', (code, signal) => {
  process.exitCode = code ?? (signal ? 1 : 0);
});
import { execFileSync, spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { classifyChangedFiles } from './ci-change-plan.mjs';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const npmExecPath = process.env.npm_execpath;
const insideDocker = process.env.CI_LOCAL_DOCKER === '1';

function git(args, { allowFailure = false } = {}) {
  try {
    return execFileSync('git', args, { cwd: repoRoot, encoding: 'utf8' }).trim();
  } catch (error) {
    if (allowFailure) return '';
    throw error;
  }
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function lines(value) {
  return value ? value.split(/\r?\n/).filter(Boolean) : [];
}

export function resolveBaseRef() {
  const requested = process.env.CI_LOCAL_BASE?.trim();
  const candidates = unique([requested, 'origin/main', 'main']);

  for (const candidate of candidates) {
    if (git(['rev-parse', '--verify', '--quiet', candidate], { allowFailure: true })) {
      return candidate;
    }
  }

  return null;
}

export function resolveLocalChangedFiles(baseRef) {
  const changed = [];

  if (baseRef) {
    changed.push(
      ...lines(
        git(['diff', '--name-only', '--diff-filter=ACMRTUXB', `${baseRef}...HEAD`], {
          allowFailure: true,
        }),
      ),
    );
  }

  // Include tracked and untracked working-tree changes so the command is useful
  // before a commit as well as immediately before a push.
  changed.push(
    ...lines(
      git(['diff', '--name-only', '--diff-filter=ACMRTUXB', 'HEAD'], { allowFailure: true }),
    ),
    ...lines(git(['ls-files', '--others', '--exclude-standard'], { allowFailure: true })),
  );

